<?php
// Integration checks. Run only against the isolated development router on port 8097.
$base='http://127.0.0.1:8097';$cookie=tempnam(sys_get_temp_dir(),'parthvi-manager-');$passed=0;
function req($path,$data=null){global $base,$cookie;$c=curl_init($base.$path);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_COOKIEJAR=>$cookie,CURLOPT_COOKIEFILE=>$cookie]);if($data!==null){curl_setopt($c,CURLOPT_POST,true);curl_setopt($c,CURLOPT_POSTFIELDS,$data);}$raw=curl_exec($c);if($raw===false)throw new Exception(curl_error($c));$n=curl_getinfo($c,CURLINFO_HEADER_SIZE);$code=curl_getinfo($c,CURLINFO_RESPONSE_CODE);curl_close($c);return ['status'=>$code,'body'=>substr($raw,$n),'headers'=>substr($raw,0,$n)];}
function ok($value,$message){global $passed;if(!$value)throw new Exception('FAIL: '.$message);$passed++;echo "PASS: $message\n";}
function editor($html){$doc=new DOMDocument();@$doc->loadHTML($html);$xp=new DOMXPath($doc);$out=[];foreach($xp->query('//form[contains(@class,"editor-form")]//input | //form[contains(@class,"editor-form")]//textarea') as $f){$name=$f->getAttribute('name');$type=$f->getAttribute('type');if(!$name||in_array($type,['file','submit'])||($type==='checkbox'&&!$f->hasAttribute('checked')))continue;$out[$name]=$f->nodeName==='textarea'?$f->textContent:$f->getAttribute('value');}return $out;}
function csrf($html){preg_match('/name="csrf" value="([a-f0-9]+)"/',$html,$m);return $m[1]??'';}
function page_form($slug){return editor(req('/admin/index.php?section=pages&slug='.$slug)['body']);}
function item_id($html,$name){$d=new DOMDocument();@$d->loadHTML($html);$xp=new DOMXPath($d);foreach($xp->query('//tr') as $r)if(str_contains($r->textContent,$name)){foreach($xp->query('.//a[contains(@href,"edit=")]',$r) as $a){parse_str(parse_url($a->getAttribute('href'),PHP_URL_QUERY),$q);return $q['edit'];}}return null;}
try{
 $r=req('/admin/login.php');$r=req('/admin/login.php',['csrf'=>csrf($r['body']),'email'=>'admin@gmail.com','password'=>getenv('PARTHVI_TEST_PASSWORD')?:'123456']);ok($r['status']===302,'Category SEO test sign-in');
 $r=req('/categories/dehydrated-white-onion');ok($r['status']===200&&str_contains($r['body'],'Dehydrated White Onion from India'),'Multi-product category has a descriptive landing page');ok(str_contains($r['body'],'"@type":"CollectionPage"')&&str_contains($r['body'],'"@type":"ItemList"'),'Category collection structured data');
 $r=req('/categories/natural-powders');ok($r['status']===301&&str_contains($r['headers'],'products/moringa-powder'),'Single-product category redirects to its product');ok(!str_contains(req('/sitemap.xml')['body'],'/categories/natural-powders</loc>'),'Single-product category is not a duplicate sitemap entry');
 $id=item_id(req('/admin/index.php?section=categories')['body'],'Dehydrated White Onion');$url='/admin/index.php?section=categories&edit='.$id;$f=editor(req($url)['body']);$f['heading']='Managed onion range';$f['intro']='Managed category introduction';$f['buying_notes']='Managed buyer guidance';$f['seo_title']='Managed category search title';$f['seo_description']='Managed category search description';ok(req($url,$f)['status']===302,'Category landing content and metadata save');$body=req('/categories/dehydrated-white-onion')['body'];foreach(['Managed onion range','Managed category introduction','Managed buyer guidance','Managed category search title','Managed category search description'] as $text)ok(str_contains($body,$text),'Public category reflects '.$text);
 $f=editor(req($url)['body']);$f['slug']='white-onion-range';req($url,$f);$r=req('/categories/dehydrated-white-onion');ok($r['status']===301&&str_contains($r['headers'],'categories/white-onion-range'),'Old category URL redirects after slug edit');ok(str_contains(req('/sitemap.xml')['body'],'/categories/white-onion-range</loc>')&&!str_contains(req('/sitemap.xml')['body'],'/categories/dehydrated-white-onion</loc>'),'Sitemap contains only current category canonical');
 $f=editor(req($url)['body']);unset($f['published']);req($url,$f);ok(req('/categories/white-onion-range')['status']===404&&req('/products/white-onion-flakes')['status']===404,'Draft category hides category and product pages');ok(!str_contains(req('/sitemap.xml')['body'],'/categories/white-onion-range</loc>'),'Draft category is excluded from sitemap');$f=editor(req($url)['body']);$f['published']='1';$f['slug']='dehydrated-white-onion';req($url,$f);ok(req('/categories/dehydrated-white-onion')['status']===200&&req('/categories/white-onion-range')['status']===301,'Restoring category URL retains redirect history');
 $f=page_form('site');$f['copy_google_verification']='test-verification-token';req('/admin/index.php?section=pages&slug=site',$f);ok(str_contains(req('/')['body'],'name="google-site-verification" content="test-verification-token"'),'Search Console token is manageable');
 $f=editor(req($url)['body']);$f['slug']='dehydrated-garlic';$r=req($url,$f);ok(str_contains($r['body'],'Another category already uses that URL'),'Duplicate category URLs are rejected');
 echo "\n$passed category SEO checks passed.\n";
}finally{unlink($cookie);}
